@@ AccountARRHandler.handle @@
     public void handle(List<Account> accounts) {
         for (Account a : accounts) {
             a.Health_Score__c = computeHealth(a);
+            a.ARR__c = calculateARR(a.Id);
         }
     }
+
+    private Decimal calculateARR(Id accountId) {
+        Decimal arr = 0;
+        for (Contract c : [SELECT AnnualValue__c FROM Contract
+                           WHERE AccountId = :accountId AND Status = 'Activated']) {
+            arr += c.AnnualValue__c;
+        }
+        return arr;
+    }

@@ OpportunityTriggerHandler.beforeUpdate @@
     private void beforeUpdate(List<Opportunity> opps) {
         applyStageGating(opps);
+        for (Opportunity o : opps) {
+            if (o.Discount__c != null) {
+                o.Discount__c = o.Discount__c.setScale(2, RoundingMode.HALF_UP);
+            }
+        }
     }
